package com.example.campsitelottery

import java.util.Date

/**
 * A user's written review of a campsite. Each user has at most one review per
 * campsite; posting again replaces it.
 *
 * @property userId ID of the user who wrote the review.
 * @property authorName The author's profile name when the review was posted.
 * @property text The review itself.
 * @property updatedAt When the review was last posted or edited, or null if unknown.
 */
data class Review(
    var userId: String = "",
    var authorName: String = "",
    var text: String = "",
    var updatedAt: Date? = null,
)
